The root cause is ts-order-other-service, with its slowness passing through security and preserve to the dashboard. The survey's other flagged services are downstream or background noise.

```json
{
  "root_causes": [
    {
      "service": "ts-order-other-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name, p.span_name, COUNT(*) n, ROUND(quantile_cont(p.duration/1e6,0.5),1) p_total_p50, ROUND(quantile_cont((p.duration - COALESCE(c.dsum,0))/1e6,0.5),1) own_p50, ROUND(quantile_cont(COALESCE(c.dsum,0)/1e6,0.5),1) child_p50 FROM abnormal_traces p LEFT JOIN (SELECT parent_span_id, trace_id, SUM(duration) dsum FROM abnormal_traces GROUP BY 1,2) c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name IN ('ts-security-service','ts-order-other-service') AND p.attr_span_kind IN ('Internal','Server') AND p.duration > 100000000 GROUP BY 1,2 ORDER BY n DESC LIMIT 12",
          "claim": "In ts-order-other-service, slow time sits in DB child spans (SELECT other.entity.Order ~208ms, Transaction.commit own ~210ms) while its own code is ~0.6ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, SUM(CASE WHEN src='n' THEN 1 ELSE 0 END) n_norm, SUM(CASE WHEN src='a' THEN 1 ELSE 0 END) n_abn, ROUND(quantile_cont(CASE WHEN src='n' THEN duration/1e6 END,0.95),1) p95_norm, ROUND(quantile_cont(CASE WHEN src='a' THEN duration/1e6 END,0.95),1) p95_abn FROM (SELECT 'n' src, * FROM normal_traces UNION ALL SELECT 'a', * FROM abnormal_traces) WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' GROUP BY 1 ORDER BY n_norm DESC",
          "claim": "User-facing refresh of order-other rose from p95 3.1ms to 430ms; admin-order GET p95 18ms to 913ms."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, ROUND(AVG(value),2) avg_v, ROUND(MAX(value),2) mx FROM abnormal_metrics WHERE service_name='ts-order-other-service' AND metric IN ('container.cpu.usage','jvm.system.cpu.load_1m','queueSize') GROUP BY 1,2",
          "claim": "order-other CPU stays low (container.cpu.usage avg 0.02), so the slowdown is not CPU saturation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-order-other-service",
      "to": "ts-admin-order-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, c.service_name AS callee, c.span_name, COUNT(*) n, ROUND(quantile_cont(c.duration/1e6,0.95),1) callee_p95, ROUND(quantile_cont(p.duration/1e6,0.95),1) caller_p95 FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-admin-order-service' AND c.service_name='ts-order-other-service' GROUP BY 1,2,3",
          "claim": "admin-order's calls to order-other take 565-951ms p95 in the abnormal period, and admin-order's own spans inherit the delay."
        }
      ]
    },
    {
      "from": "ts-admin-order-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, c.service_name AS callee, c.span_name, COUNT(*) n, ROUND(quantile_cont(c.duration/1e6,0.95),1) callee_p95 FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-admin-order-service' GROUP BY 1,2,3",
          "claim": "ui-dashboard's calls to admin-order take 300-1380ms p95 for GET, PUT and DELETE adminorder, versus about 10-20ms normally."
        }
      ]
    },
    {
      "from": "ts-order-other-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, c.service_name AS callee, c.span_name, COUNT(*) n, ROUND(quantile_cont(c.duration/1e6,0.95),1) callee_p95 FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-order-other-service' GROUP BY 1,2,3",
          "claim": "ui-dashboard's POST orderOther/refresh calls to order-other slowed to about 430ms p95 in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-order-other-service",
      "to": "ts-security-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.trace_id, ROUND(p.duration/1e6,1) check_ms, c.span_name child, c.service_name child_svc, ROUND(c.duration/1e6,1) child_ms FROM abnormal_traces p LEFT JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-security-service' AND p.span_name='SecurityController.check' ORDER BY p.duration DESC",
          "claim": "In the slow security check, a single outbound GET child takes about 1280ms, while its own repository call takes about 2ms."
        }
      ]
    },
    {
      "from": "ts-security-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, c.service_name AS callee, c.span_name, COUNT(*) n, ROUND(quantile_cont(c.duration/1e6,0.95),1) callee_p95 FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-preserve-service' AND c.service_name='ts-security-service' GROUP BY 1,2,3",
          "claim": "preserve's GET securityConfigs calls to security take about 1241ms p95 in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, SUM(CASE WHEN src='n' THEN 1 ELSE 0 END) n_norm, SUM(CASE WHEN src='a' THEN 1 ELSE 0 END) n_abn, ROUND(quantile_cont(CASE WHEN src='n' THEN duration/1e6 END,0.95),1) p95_norm, ROUND(quantile_cont(CASE WHEN src='a' THEN duration/1e6 END,0.95),1) p95_abn FROM (SELECT 'n' src, * FROM normal_traces UNION ALL SELECT 'a', * FROM abnormal_traces) WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name='POST /api/v1/preserveservice/preserve' GROUP BY 1",
          "claim": "User-facing POST preserve latency rose from p95 150ms to 1259ms, and volume fell from 45 to 3 requests."
        }
      ]
    }
  ]
}
```

